INSERT INTO build_status VALUES ('R178','experiment/drnas-r178-mixed-spectrum100-20261106','FINAL_AUDIT_PASS_192_OF_200_SOLVED_EACH_MODE','https://github.com/Frane12/AndroidGameTest/actions/runs/42189798453','10/10 shards success and final SHA/pinned binary/independent source GF2 replay audit success, 100 mixed formulas x2 x4=800. CaDiCaL 722.594324 PAR2 vs R174-B 727.817211, R177-OneHop 730.473612, TwoHop 730.831894. 96 generated planted SAT all solved, 4 known real original hard mixed all timeout. NOT BLIND; no breakthrough.') ON CONFLICT(version) DO UPDATE SET branch=excluded.branch,status=excluded.status,last_evidence_url=excluded.last_evidence_url,notes=excluded.notes;
